import sys
import json
import re

# ---------------------------------------------------------------
# Set Variables
# ---------------------------------------------------------------
raw_arg1 = sys.argv[1]
raw_arg2 = sys.argv[2]
NO_OUTPUT_MARKER = "No-Matching-Output"

# argv[1]: may be raw error message string OR a wrapping JSON dict
try:
    parsed = json.loads(raw_arg1)
    json_response = parsed if isinstance(parsed, dict) else {"output": {"error": {"message": raw_arg1}}}
except Exception:
    json_response = {"output": {"error": {"message": raw_arg1}}}

# argv[2]: JSON list of commands
try:
    COMMANDS = json.loads(raw_arg2)
    if not isinstance(COMMANDS, list):
        raise ValueError
except Exception:
    COMMANDS = [c.strip().strip('"').strip("'") for c in raw_arg2.split(",") if c.strip()]


# ---------------------------------------------------------------
# Definitions
# ---------------------------------------------------------------
def clean_output(raw: str, command: str) -> str:
    if not raw:
        return ""
    lines = raw.splitlines()
    if lines and lines[0].strip() == command.strip():
        lines = lines[1:]
    if lines and re.match(r"^\S+[#>]\s*$", lines[-1].strip()):
        lines = lines[:-1]
    return "\n".join(l for l in lines if l.strip()).strip()


def extract_command_outputs(response: dict, commands: list) -> dict:
    results = {cmd: NO_OUTPUT_MARKER for cmd in commands}

    error_message = response.get("output", {}).get("error", {}).get("message", "")
    if not error_message:
        return results

    match = re.search(r"body=(\[.*\])\s*$", error_message, re.DOTALL)
    if not match:
        return results

    body_text = match.group(1)

    # 🔧 Escape raw control characters that break json.loads
    body_text = re.sub(r'(?<!\\)\n', r'\\n', body_text)
    body_text = re.sub(r'(?<!\\)\r', r'\\r', body_text)
    body_text = re.sub(r'(?<!\\)\t', r'\\t', body_text)

    try:
        body_data = json.loads(body_text)
    except json.JSONDecodeError as e:
        print(f"[!] Failed to parse embedded JSON body: {e}")
        return results

    for entry in body_data:
        success_block = entry.get("commandResponses", {}).get("SUCCESS", {})
        for cmd in commands:
            raw_output = success_block.get(cmd, "")
            cleaned = clean_output(raw_output, cmd)
            results[cmd] = cleaned if cleaned else NO_OUTPUT_MARKER
    return results


def build_report_string(extracted: dict) -> str:
    parts = ["=" * 70, "EXTRACTED COMMAND OUTPUTS", "=" * 70]
    for cmd, output in extracted.items():
        parts += ["", f">>> Command: {cmd}", "-" * 70, output]
    return "\n".join(parts)


# ---------------------------------------------------------------
# Main
# ---------------------------------------------------------------
extracted  = extract_command_outputs(json_response, COMMANDS)
report_str = build_report_string(extracted)

# print(report_str)   # ← workflow engines capture stdout
